import {choice,text,fields,validation} from '@crew/shared';
import {listIssues,getIssue} from '../work/issues.js';
const kinds=['organizations','projects','issues','users'];
const permissions=['insight:read','project:read','export:read','issue:write'];
function queryId(value,field){return value===undefined||value===''?null:text(value,field,{max:128});}
function matches(item,query){return !query||(item.label+' '+item.description).toLocaleLowerCase().includes(query);}
function projectOption(row){return {id:row.id,label:row.key+' · '+row.name,description:row.description??'',key:row.key,name:row.name,orgId:row.org_id,archived:Boolean(row.archived)};}
function issueOption(issue){return {id:issue.id,label:issue.key+' · '+issue.title,description:issue.statusName+' · '+(issue.assignee?.name??'Unassigned'),key:issue.key,title:issue.title,projectId:issue.projectId,orgId:issue.orgId};}
export function entityOptions(ctx,req) {
  const input=fields(req.query,['type','permission','orgId','projectId','id','q','limit','cursor']);
  const type=choice(input.type,'type',kinds),permission=choice(input.permission,'permission',permissions,'insight:read');
  ctx.permissions.scope(req,permission);
  const orgId=queryId(input.orgId,'orgId'),projectId=queryId(input.projectId,'projectId'),selectedId=queryId(input.id,'id');
  const q=text(input.q??'','q',{min:0,max:200}).toLocaleLowerCase();
  let items;
  if(type==='organizations') {
    ctx.permissions.scope(req,'org:read');
    items=ctx.db.prepare('SELECT o.*,m.role FROM organizations o JOIN memberships m ON m.org_id=o.id WHERE m.user_id=? ORDER BY o.name,o.id').all(req.user.id)
      .map(row=>({id:row.id,label:row.name,description:row.role,name:row.name,role:row.role}));
  }else{
    if(!orgId)throw validation({orgId:'Choose an organization first'});
    ctx.permissions.assertOrg(req,orgId,'org:read');
    if(projectId){const project=ctx.permissions.assertProject(req,projectId,permission);if(project.org_id!==orgId)throw validation({projectId:'Project belongs to another organization'});}
    if(type==='users') {
      items=ctx.db.prepare("SELECT u.id,u.name,u.email,m.role FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.org_id=? AND m.role<>'guest' ORDER BY u.name,u.id").all(orgId)
        .map(row=>({id:row.id,label:row.name,description:row.email+' · '+row.role,name:row.name,email:row.email,role:row.role}));
    }else{
      const projects=ctx.db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY key,id').all(orgId)
        .filter(row=>(!projectId||row.id===projectId)&&ctx.permissions.canProject(req.user.id,row.id,permission));
      if(type==='projects')items=projects.map(projectOption);
      else if(selectedId){
        const allowed=new Set(projects.map(row=>row.id));
        const row=ctx.db.prepare('SELECT project_id FROM issues WHERE id=?').get(selectedId);
        items=row&&allowed.has(row.project_id)?[issueOption(getIssue(ctx,selectedId))]:[];
      }else items=projects.flatMap(project=>listIssues(ctx,project.id)).map(issueOption).sort((a,b)=>a.key.localeCompare(b.key,undefined,{numeric:true})||a.id.localeCompare(b.id));
    }
  }
  const visible=items.filter(item=>selectedId?item.id===selectedId:matches(item,q));
  return {...ctx.paginate(visible,input),total:visible.length};
}
export function registerOptionRoutes(ctx) {
  ctx.app.get('/api/v1/insight/options',ctx.requireAuth,(req,res)=>res.json(entityOptions(ctx,req)));
}

export function pickerScope({type,orgId,projectId,permission}) {
  return JSON.stringify([type,orgId??'',projectId??'',permission??'insight:read']);
}
export function emptyPicker(scope) {
  return {scope,draft:'',query:'',cursor:'',history:[]};
}
export function scopedPicker(state,scope) {
  return state.scope===scope?state:emptyPicker(scope);
}
export function pickerAction(state,action) {
  if(action.type==='draft')return {...state,draft:action.value};
  if(action.type==='search')return {...state,query:state.draft.trim(),cursor:'',history:[]};
  if(action.type==='next'&&action.cursor)return {...state,cursor:action.cursor,history:[...state.history,state.cursor]};
  if(action.type==='previous'&&state.history.length)return {...state,cursor:state.history.at(-1),history:state.history.slice(0,-1)};
  return state;
}
export function selectedOption(items,id,loaded) {
  return items.find(item=>item.id===id)??loaded?.items?.find(item=>item.id===id)??null;
}
export function optionDescription(item) {
  return item?[item.label,item.description].filter(Boolean).join(' — '):'';
}

import {useEffect,useId,useState} from 'preact/hooks';
import {Button,Notice,useLoad} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {pickerScope,emptyPicker,scopedPicker,pickerAction,selectedOption,optionDescription} from './selector-state.js';
export function EntityPicker({api,type,orgId,projectId,permission='insight:read',value='',onChange,label,required=false,disabled=false,placeholder='Choose an item'}) {
  const scope=pickerScope({type,orgId,projectId,permission});
  const [saved,setSaved]=useState(()=>emptyPicker(scope));
  const state=scopedPicker(saved,scope),fieldId=useId();
  const enabled=!disabled&&(type==='organizations'||Boolean(orgId));
  const parameters={type,orgId:type==='organizations'?undefined:orgId,projectId,permission};
  const load=useLoad(()=>enabled?api.get('/insight/options?'+queryString({...parameters,q:state.query,cursor:state.cursor,limit:20})):Promise.resolve({items:[],total:0,nextCursor:null}),[scope,state.query,state.cursor,enabled]);
  const selected=useLoad(()=>enabled&&value?api.get('/insight/options?'+queryString({...parameters,id:value,limit:1})):Promise.resolve({items:[]}),[scope,value,enabled]);
  useEffect(()=>{if(saved.scope!==scope)setSaved(emptyPicker(scope));},[scope]);
  const items=load.loading?[]:load.data?.items??[];
  const current=selectedOption(items,value,selected.loading?null:selected.data);
  function dispatch(action){setSaved(previous=>pickerAction(scopedPicker(previous,scope),action));}
  function choose(event){const id=event.currentTarget.value;onChange?.(id,items.find(item=>item.id===id)??current);}
  return <fieldset className="entity-picker" disabled={!enabled}>
    <legend>{label}</legend>
    <div className="picker-search"><label htmlFor={fieldId+'-search'}>Search {label.toLowerCase()}</label>
      <input id={fieldId+'-search'} type="search" autoComplete="off" value={state.draft} onInput={event=>dispatch({type:'draft',value:event.currentTarget.value})} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();dispatch({type:'search'});}}}/>
      <Button type="button" onClick={()=>dispatch({type:'search'})}>Search</Button>
    </div>
    <Notice error={load.error??selected.error}/>
    <label htmlFor={fieldId+'-results'} className="sr-only">{label} search results</label>
    <select id={fieldId+'-results'} size="5" value={value} required={required} aria-busy={load.loading} aria-describedby={fieldId+'-status'} onChange={choose}>
      {!required&&<option value="">{placeholder}</option>}
      {value&&!items.some(item=>item.id===value)&&<option value={value}>{current?.label??(selected.loading?'Loading selected item…':'Selected item is unavailable')}</option>}
      {items.map(item=><option key={item.id} value={item.id}>{item.label}{item.archived?' (archived)':''}</option>)}
    </select>
    <p id={fieldId+'-status'} role="status">{!enabled?'Choose an organization first.':load.loading?'Loading options…':load.error?'Options could not be loaded.':load.data?.total===0?'No matching accessible items.':(load.data?.total??0)+' matching accessible items.'}</p>
    {current&&<p className="picker-selection">Selected: {optionDescription(current)}</p>}
    <div className="pagination"><Button type="button" disabled={!state.history.length||load.loading} onClick={()=>dispatch({type:'previous'})}>Previous {label.toLowerCase()}</Button>
      <Button type="button" disabled={!load.data?.nextCursor||load.loading} onClick={()=>dispatch({type:'next',cursor:load.data.nextCursor})}>Next {label.toLowerCase()}</Button>
      <Button type="button" busy={load.loading} onClick={()=>{load.reload();selected.reload();}}>Reload options</Button>
      {!required&&value&&<Button type="button" onClick={()=>onChange?.('',null)}>Clear selection</Button>}
    </div>
  </fieldset>;
}
